import { preview } from 'vite'
import { chromium } from '@playwright/test'
import { cp, mkdir, readFile, readdir, stat, writeFile } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import path from 'node:path'

const root = 'benchmark-results/heavy-scenes/', base = '49148fae5a22aaf953faadfd13bc3ac2b7e384b3'
const smoke = process.argv.includes('--smoke'), suffix = smoke ? '-smoke' : ''
const output = `${root}production-frame${suffix}-2026-10-27.json`
const frozen = `${root}production-frame-dist-2026-10-27`
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim()
if (git('rev-parse', 'HEAD') !== base || git('diff', 'HEAD', '--name-only', '--', 'src', 'tests', 'package.json', 'package-lock.json', 'vite.config.ts')) throw Error('Unexpected production source revision')
async function manifest(dir, prefix = '') {
  const rows = []
  for (const entry of await readdir(path.join(dir, prefix), { withFileTypes: true })) {
    const relative = path.posix.join(prefix, entry.name)
    if (entry.isDirectory()) rows.push(...await manifest(dir, relative))
    else if (entry.isFile()) { const bytes = await readFile(path.join(dir, relative)); rows.push({ path: relative, bytes: bytes.length, sha256: sha(bytes) }) }
    else throw Error('Unexpected non-file in build')
  }
  return rows.sort((a, b) => a.path.localeCompare(b.path))
}
const buildFiles = await manifest('dist')
if (!existsSync(frozen)) await cp('dist', frozen, { recursive: true, force: false, errorOnExist: true })
if (JSON.stringify(await manifest(frozen)) !== JSON.stringify(buildFiles)) throw Error('Frozen production bundle differs')
const html = await readFile(frozen + '/index.html', 'utf8')
const entryPath = html.match(/<script\b[^>]*\bsrc=["']([^"']+\.js)["']/)?.[1]
if (!entryPath?.startsWith('/titan-engine-dev/assets/')) throw Error('Unexpected production base')
const runtimeNames = (await readdir(frozen + '/assets')).filter(name => /^simulationRuntime-.*\.js$/.test(name))
if (runtimeNames.length !== 1) throw Error('Runtime bundle not unique')
const runtimePath = '/titan-engine-dev/assets/' + runtimeNames[0]
const probePath = root + 'production-frame-2026-10-27.browser.js'
const report = { base, startedAt: new Date().toISOString(), smoke, buildFiles, frozenBundle: frozen,
  sourceHashes: Object.fromEntries(await Promise.all([probePath, root + 'run-production-frame-2026-10-27.mjs', 'src/core/Engine.ts', 'src/core/graphic/passes/DepthVolumeResolutionRenderer.ts', 'src/core/graphic/passes/DepthVolumeReconstructionRenderer.ts'].map(async p => [p, sha(await readFile(p))]))),
  rows: [], scenes: [], errors: [], warnings: [], assetFailures: [], abortedRequests: [], cloudResponses: 0, sourceModuleRequests: [], outcome: 'failed' }
await writeFile(output, JSON.stringify(report, null, 2), { flag: 'wx' })
let server, browser
const persist = () => writeFile(output, JSON.stringify(report, null, 2))
try {
  server = await preview({ build: { outDir: frozen }, base: '/titan-engine-dev/', preview: { host: '127.0.0.1', port: 8096, strictPort: true } })
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`); if (r.url().startsWith('https://storage.yandexcloud.net/') && r.ok()) report.cloudResponses++ })
  page.on('request', r => { if (/http:\/\/127\.0\.0\.1:8096\/(?:src|@vite|@id|tests)\//.test(r.url())) report.sourceModuleRequests.push(r.url()) })
  page.on('requestfailed', r => (r.failure()?.errorText?.includes('ERR_ABORTED') ? report.abortedRequests : report.assetFailures).push(`${r.failure()?.errorText} ${r.url()}`))
  await page.goto('http://127.0.0.1:8096/titan-engine-dev/')
  await page.getByRole('button', { name: /^Run / }).first().waitFor()
  await page.addScriptTag({ path: probePath, type: 'module' })
  await page.waitForFunction(() => !!window.__productionFrame)
  report.connection = await page.evaluate(async ({ entryPath, runtimePath }) => window.__productionFrame.connect(entryPath, runtimePath), { entryPath, runtimePath })
  const cdp = await page.context().newCDPSession(page)
  const cases = smoke ? [[13, 135]] : [[13, 135], [12, 127]]
  for (const [id, actor] of cases) {
    console.log('Starting production scenario', id)
    const scene = await page.evaluate(async id => Promise.race([window.__productionFrame.selectScenario(id), new Promise((_, reject) => setTimeout(() => reject(Error('Startup timeout')), 180000))]), id)
    if (/SwiftShader|software|llvmpipe/i.test(scene.renderer)) throw Error('Software renderer')
    report.scenes.push(scene); await persist()
    const windows = smoke ? ['plain', 'gpu-frame', 'passes', 'volumes', 'cpu'].map(mode => ({ mode, motion: true, repetition: 0 })) : [
      ...Array.from({ length: 3 }, (_, repetition) => [false, true].map(motion => ({ mode: 'plain', motion, repetition }))).flat(),
      ...['gpu-frame', 'passes', 'volumes'].flatMap(mode => [false, true].map(motion => ({ mode, motion, repetition: 0 }))),
      { mode: 'cpu', motion: true, repetition: 0 }
    ]
    for (const window of windows) {
      const view = await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
      await page.evaluate(async () => window.__productionFrame.settle(64))
      const profileCpu = !smoke && window.mode === 'cpu'
      if (profileCpu) { await cdp.send('Profiler.enable'); await cdp.send('Profiler.setSamplingInterval', { interval: 1000 }); await cdp.send('Profiler.start') }
      const result = await page.evaluate(options => window.__productionFrame.measure(options), { ...window, frames: smoke ? 8 : 240 })
      if (profileCpu) {
        const { profile } = await cdp.send('Profiler.stop'); await cdp.send('Profiler.disable')
        const profilePath = `${root}production-frame-2026-10-27-${id}.cpuprofile`
        await writeFile(profilePath, JSON.stringify(profile), { flag: 'wx' })
        result.cpuProfile = { path: profilePath, sha256: sha(await readFile(profilePath)) }
      }
      report.rows.push({ id, ...window, view, ...result }); await persist()
      console.log('PRODUCTION_FRAME', id, window.mode, window.motion, window.repetition, JSON.stringify(result.summary))
      if (report.errors.length || report.warnings.length || report.assetFailures.length || report.abortedRequests.length || report.sourceModuleRequests.length) throw Error('Browser/asset/source-module issue')
    }
    await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
    await page.evaluate(async () => window.__productionFrame.settle(64))
    const screenshot = `${root}production-frame${suffix}-2026-10-27-${id}.png`
    await page.screenshot({ path: screenshot })
    report.scenes.at(-1).screenshot = { path: screenshot, sha256: sha(await readFile(screenshot)) }
    report.scenes.at(-1).afterMenu = await page.evaluate(() => window.__productionFrame.menu())
    await persist()
  }
  if (report.errors.length || report.warnings.length || report.assetFailures.length || report.abortedRequests.length || report.sourceModuleRequests.length || !report.cloudResponses) throw Error('Final browser/asset/source verification failed')
  if (JSON.stringify(await manifest(frozen)) !== JSON.stringify(buildFiles)) throw Error('Served bundle mutated')
  report.outcome = 'completed'
} catch (error) { report.failure = error.stack || error.message; console.error(error); process.exitCode = 1 }
finally {
  report.finishedAt = new Date().toISOString(); await persist()
  await browser?.close()
  if (server) await new Promise(resolve => server.httpServer.close(resolve))
}

