import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import assert from 'node:assert/strict'

const root = 'benchmark-results/heavy-scenes/'
const output = 'docs/benchmarks/production-frame-2026-10-27.json'
const base = '49148fae5a22aaf953faadfd13bc3ac2b7e384b3'
const sha = value => createHash('sha256').update(value).digest('hex')
const read = path => {
  const bytes = readFileSync(path)
  return bytes[0] === 255 && bytes[1] === 254 ? bytes.subarray(2).toString('utf16le') : bytes.toString('utf8').replace(/^\uFEFF/, '')
}
const json = path => JSON.parse(read(path))
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim()
const normalize = text => text.replaceAll('\r\n', '\n')
const stats = values => {
  const sorted = values.slice().sort((a, b) => a - b)
  if (!sorted.length) return { count: 0 }
  const q = p => sorted[Math.ceil(sorted.length * p) - 1]
  return { count: sorted.length, p50: q(.5), p95: q(.95), p99: q(.99), max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
}
const sourcePaths = [
  'package.json', 'vite.config.ts', 'src/core/Engine.ts', 'src/core/graphic/Postprocessing.ts',
  'src/ui/runtime/simulationRuntime.tsx', 'src/core/framework/container/Container.ts',
  ...['DepthVolumePass', 'DepthVolumeResolutionRenderer', 'DepthVolumeReconstructionRenderer', 'DepthVolumeHistory'].map(name => `src/core/graphic/passes/${name}.ts`),
  'node_modules/three/src/renderers/WebGLRenderer.js', 'node_modules/three/src/renderers/webgl/WebGLTextures.js',
  'node_modules/three/src/core/RenderTarget.js',
  ...['production-frame-2026-10-27.browser.js', 'run-production-frame-2026-10-27.mjs',
    'production-frame-smoke-first-2026-10-27.browser.txt', 'run-production-frame-smoke-first-2026-10-27.txt',
    'archive-production-frame-2026-10-27.mjs'].map(name => root + name),
  'docs/superpowers/plans/2026-10-27-production-frame.md'
]
const evidencePaths = ['package-lock.json', ...[
  'production-frame-build-2026-10-27.log', 'production-frame-2026-10-27.json', 'production-frame-2026-10-27.log',
  'production-frame-smoke-first-2026-10-27.json', 'production-frame-smoke-first-2026-10-27.log',
  'production-frame-smoke-2026-10-27.json', 'production-frame-smoke-2026-10-27.log',
  'production-frame-2026-10-27-13.cpuprofile', 'production-frame-2026-10-27-12.cpuprofile',
  'production-frame-2026-10-27-13.png', 'production-frame-2026-10-27-12.png', 'production-frame-smoke-2026-10-27-13.png'
].map(name => root + name)]
const reviewPath = root + 'production-frame-review-2026-10-27.json'

function manifest(dir, prefix = '') {
  return readdirSync(dir + (prefix ? '/' + prefix : ''), { withFileTypes: true }).flatMap(entry => {
    const path = prefix ? `${prefix}/${entry.name}` : entry.name
    if (entry.isDirectory()) return manifest(dir, path)
    assert(entry.isFile(), path)
    const bytes = readFileSync(`${dir}/${path}`)
    return [{ path, bytes: bytes.length, sha256: sha(bytes) }]
  }).sort((a, b) => a.path.localeCompare(b.path))
}
function checkReport(report, smoke = false) {
  assert.equal(report.base, base); assert.equal(report.outcome, 'completed'); assert.equal(report.smoke, smoke)
  assert(Date.parse(report.finishedAt) > Date.parse(report.startedAt)); assert(report.cloudResponses > 0)
  for (const key of ['errors', 'warnings', 'assetFailures', 'abortedRequests', 'sourceModuleRequests']) assert.deepEqual(report[key], [], key)
  assert.equal(report.rows.length, smoke ? 5 : 26)
  assert.equal(report.scenes.length, smoke ? 1 : 2)
  for (const [path, hash] of Object.entries(report.sourceHashes)) assert.equal(sha(readFileSync(path)), hash, path)
  assert.deepEqual(report.buildFiles, manifest(report.frozenBundle))
  assert.deepEqual(report.buildFiles, manifest('dist'))
  for (const scene of report.scenes) {
    assert.match(scene.renderer, /ANGLE \(AMD,/); assert.doesNotMatch(scene.renderer, /SwiftShader|software|llvmpipe/i)
    assert.deepEqual(scene.viewport, [1280, 720]); assert.equal(scene.dpr, 1)
    assert.equal(sha(readFileSync(scene.screenshot.path)), scene.screenshot.sha256)
    assert.equal(scene.afterMenu.scenario, null); assert.equal(scene.afterMenu.pendingBakes, 0); assert.equal(scene.afterMenu.bakeBytes, 0)
    assert.deepEqual(scene.afterMenu.memory, { geometries: 1, textures: 0 }); assert.equal(scene.afterMenu.programs, 0)
    assert.deepEqual(scene.afterMenu.streamers, []); assert.deepEqual(scene.afterMenu.volumes, [])
    const rows = report.rows.filter(row => row.id === scene.id)
    const expected = smoke ? ['plain', 'gpu-frame', 'passes', 'volumes', 'cpu'].map(mode => [mode, true, 0]) : [
      ...Array.from({ length: 3 }, (_, rep) => [false, true].map(motion => ['plain', motion, rep])).flat(),
      ...['gpu-frame', 'passes', 'volumes'].flatMap(mode => [false, true].map(motion => [mode, motion, 0])), ['cpu', true, 0]
    ]
    assert.deepEqual(rows.map(row => [row.mode, row.motion, row.repetition]), expected)
  }
  for (const row of report.rows) {
    const n = smoke ? 8 : 240
    assert.equal(row.frames, n); assert.equal(row.starts.length, n); assert.equal(row.intervals.length, n - 1); assert.equal(row.wholeCpu.length, n)
    assert(row.wholeCpu.every(value => Number.isFinite(value) && value >= 0))
    assert.deepEqual(row.intervals, row.starts.slice(1).map((value, i) => value - row.starts[i])); assert(row.intervals.every(value => value > 0))
    assert.deepEqual(row.summary.intervals, stats(row.intervals)); assert.deepEqual(row.summary.wholeCpu, stats(row.wholeCpu))
    for (const state of [row.initial, row.final]) { assert.equal(state.pendingBakes, 0); assert.equal(state.scenario, row.id); assert.equal(state.dpr, 1) }
    assert.deepEqual(row.initial.camera, row.view.camera)
    assert.deepEqual(row.positions.map(p => p.frame), [0, n - 1]); assert.deepEqual(row.positions[0].position, row.view.camera)
    const distance = Math.hypot(...row.positions[1].position.map((value, i) => value - row.positions[0].position[i]))
    assert(Math.abs(distance - (row.motion ? 2 : 0)) < 1e-8)
    const dot = row.positions[0].quaternion.reduce((sum, value, i) => sum + value * row.positions[1].quaternion[i], 0)
    assert(Math.abs(Math.abs(dot) - 1) < 1e-12)
    const gpu = {}, calls = {}
    for (const sample of row.gpu) {
      assert(Number.isFinite(sample.ms) && sample.ms > 0); assert(Number.isInteger(sample.frame) && sample.frame >= 0 && sample.frame < n)
      const values = gpu[sample.key] ??= Array(n).fill(0), counts = calls[sample.key] ??= Array(n).fill(0)
      values[sample.frame] += sample.ms; counts[sample.frame]++
    }
    assert.deepEqual(row.gpuPerFrame, gpu); assert.deepEqual(row.gpuCalls, calls)
    assert.deepEqual(row.summary.gpu, Object.fromEntries(Object.entries(gpu).map(([key, values]) => [key, stats(values)])))
    for (const [key, values] of Object.entries(row.cpu)) {
      assert.equal(values.length, n); assert(values.every(v => Number.isFinite(v) && v >= 0))
      assert.equal(row.cpuCalls[key].length, n); assert(row.cpuCalls[key].every(v => Number.isInteger(v) && v >= 0))
      assert.deepEqual(row.summary.cpu[key], stats(values))
    }
    if (row.mode === 'plain') { assert.deepEqual(row.cpu, {}); assert.deepEqual(row.gpu, []); assert(!row.cpuProfile) }
    if (row.mode === 'cpu') { assert.deepEqual(row.gpu, []); assert(!Object.keys(row.cpu).some(key => key.startsWith('gl.getParameter:'))) }
    if (row.mode === 'gpu-frame') { assert.equal(row.gpu.length, n); assert(calls['whole-frame'].every(v => v === 1)) }
    if (row.mode === 'passes') { assert.equal(row.gpu.length, n * 10); assert.equal(Object.keys(calls).length, 10); assert(Object.values(calls).every(values => values.every(v => v === 1))) }
    if (row.mode === 'volumes') {
      assert(Object.keys(gpu).some(key => key.endsWith('RingDustVolume:march')))
      for (const suffix of [':matched', ':fallback', ':temporal', ':composite']) assert(Object.keys(gpu).some(key => key.endsWith(suffix)))
    }
    if (row.cpuProfile) assert.equal(sha(readFileSync(row.cpuProfile.path)), row.cpuProfile.sha256)
  }
}
function analysis(report, profiles) {
  return {
    measuredFrames: report.rows.reduce((sum, row) => sum + row.frames, 0),
    measuredIntervals: report.rows.reduce((sum, row) => sum + row.intervals.length, 0),
    plain: report.rows.filter(row => row.mode === 'plain').map(row => ({ id: row.id, motion: row.motion, repetition: row.repetition,
      intervals: stats(row.intervals), renderFrameWall: stats(row.wholeCpu),
      intervalBins: [0, 25, 50, 100, 150, 200].map((min, i, edges) => ({ minInclusiveMs: min, maxExclusiveMs: edges[i + 1] ?? null,
        count: row.intervals.filter(v => v >= min && (edges[i + 1] === undefined || v < edges[i + 1])).length })) })),
    gpu: report.rows.filter(row => ['gpu-frame', 'passes', 'volumes'].includes(row.mode)).map(row => ({ id: row.id, motion: row.motion, mode: row.mode,
      scopes: row.summary.gpu,
      sameFrameVolumeGroups: row.mode === 'volumes' ? Object.fromEntries([...new Set(Object.keys(row.gpuPerFrame).map(key => key.includes('/Nebula/Mesh:') ? key.split('/Nebula/Mesh:')[0] : key))].map(group => {
        const arrays = Object.entries(row.gpuPerFrame).filter(([key]) => key === group || key.startsWith(group + '/Nebula/Mesh:')).map(([, a]) => a)
        return [group, stats(Array.from({ length: row.frames }, (_, i) => arrays.reduce((sum, a) => sum + a[i], 0)))]
      })) : null })),
    cpu: report.rows.filter(row => row.mode === 'cpu').map(row => ({ id: row.id, renderFrameWall: row.summary.wholeCpu, nestedComponents: row.summary.cpu,
      calls: Object.fromEntries(Object.entries(row.cpuCalls).map(([key, values]) => [key, values.reduce((sum, value) => sum + value, 0)])) })),
    cdp: Object.entries(profiles).map(([id, profile]) => {
      const nodes = new Map(profile.nodes.map(node => [node.id, node])), self = new Map()
      assert.equal(profile.samples.length, profile.timeDeltas.length)
      for (let i = 0; i < profile.samples.length; i++) {
        assert(nodes.has(profile.samples[i])); assert(profile.timeDeltas[i] >= 0)
        self.set(profile.samples[i], (self.get(profile.samples[i]) ?? 0) + profile.timeDeltas[i])
      }
      return { id: Number(id), samples: profile.samples.length, durationMs: (profile.endTime - profile.startTime) / 1000,
        topSelfSampledNodes: [...self].sort((a, b) => b[1] - a[1]).slice(0, 20).map(([node, us]) => ({ sampledMs: us / 1000, ...nodes.get(node).callFrame })) }
    })
  }
}
function verify(archive) {
  assert.equal(archive.base, base)
  assert.equal(git('diff', base, '--name-only', '--', 'src', 'tests', 'package.json', 'package-lock.json', 'vite.config.ts'), '')
  for (const entry of archive.provenance) {
    const bytes = readFileSync(entry.path); assert.equal(bytes.length, entry.bytes, entry.path); assert.equal(sha(bytes), entry.sha256, entry.path)
  }
  for (const [path, value] of Object.entries(archive.sources)) {
    assert.equal(read(path), value, path)
    if (path.startsWith('src/') || ['package.json', 'vite.config.ts'].includes(path)) assert.equal(normalize(value).trim(), normalize(git('show', `${base}:${path}`)), path)
  }
  assert.deepEqual(archive.profile, json(root + 'production-frame-2026-10-27.json')); checkReport(archive.profile)
  assert.deepEqual(archive.diagnostics.smoke, json(root + 'production-frame-smoke-2026-10-27.json')); checkReport(archive.diagnostics.smoke, true)
  assert.deepEqual(archive.diagnostics.firstSmoke, json(root + 'production-frame-smoke-first-2026-10-27.json'))
  assert.equal(archive.diagnostics.firstSmoke.outcome, 'failed'); assert.match(archive.diagnostics.firstSmoke.failure, /sample.ms is not a function/)
  for (const id of [13, 12]) assert.deepEqual(archive.cpuProfiles[id], json(`${root}production-frame-2026-10-27-${id}.cpuprofile`))
  for (const [path, log] of Object.entries(archive.logs)) assert.equal(log, read(path), path)
  assert.match(archive.logs[root + 'production-frame-build-2026-10-27.log'].replace(/\x1b\[[0-9;]*m/g, ''), /built in 9\.91s/)
  assert.deepEqual(archive.analysis, analysis(archive.profile, archive.cpuProfiles))
  if (archive.review) assert.deepEqual(archive.review, json(reviewPath))
  console.log(JSON.stringify({ verified: true, hashes: archive.provenance.length, buildFiles: archive.profile.buildFiles.length,
    windows: archive.profile.rows.length, frames: archive.analysis.measuredFrames, intervals: archive.analysis.measuredIntervals, cloudResponses: archive.profile.cloudResponses }))
}

if (process.argv.includes('--verify')) verify(json(output))
else {
  const profile = json(root + 'production-frame-2026-10-27.json')
  const cpuProfiles = Object.fromEntries([13, 12].map(id => [id, json(`${root}production-frame-2026-10-27-${id}.cpuprofile`)]))
  const paths = [...sourcePaths, ...evidencePaths, ...(existsSync(reviewPath) ? [reviewPath] : [])]
  const archive = {
    base, createdAt: new Date().toISOString(), title: 'Unchanged production-frame profile: Alkaid and W26',
    sources: Object.fromEntries(sourcePaths.map(path => [path, read(path)])), profile, cpuProfiles,
    analysis: analysis(profile, cpuProfiles),
    diagnostics: { firstSmoke: json(root + 'production-frame-smoke-first-2026-10-27.json'), smoke: json(root + 'production-frame-smoke-2026-10-27.json') },
    logs: Object.fromEntries(evidencePaths.filter(path => path.endsWith('.log')).map(path => [path, read(path)])),
    verification: { buildExitCode: 0, buildViteSeconds: 9.91, sourceUnchanged: true, screenshotsViewed: [13, 12], freshApplicationTests: false,
      reason: 'Only audit documentation and this evidence archive changed; no application/test code changes. Fresh production build/typecheck, smoke, full native profile and archive checks performed.' },
    reproduction: {
      environment: { node: '24.17.0', browser: profile.scenes[0].userAgent, renderer: profile.scenes[0].renderer, viewport: [1280, 720], dpr: 1 },
      steps: [
        'Use an isolated checkout of base. npm ci; restore the embedded diagnostic sources to their recorded paths. Do not execute against a dirty application checkout.',
        'Set VITE_FS_DRIVER=s3, VITE_S3_URL=https://storage.yandexcloud.net, VITE_FILE_BUCKET=textures, VITE_SHOW_STATS_PANEL=false, VITE_SKY_SOURCE=gaia. Run npm run build -- --base=/titan-engine-dev/.',
        'Run node benchmark-results/heavy-scenes/run-production-frame-2026-10-27.mjs --smoke, then without --smoke, sequentially on native Chrome. Filenames are exclusive: use a fresh workspace/results directory; do not overwrite historical outputs.',
        'The runner freezes dist, verifies its manifest before and after, imports only retained production exports and uses the existing DI token identities. Exact historical build checksums are recorded; timestamps/cloud data/device can change new results.',
        'For original local evidence run node benchmark-results/heavy-scenes/archive-production-frame-2026-10-27.mjs --verify. This verifies original raw hashes, summaries and local bundle; newly rerun timings have different hashes.'
      ]
    },
    scope: [
      'Current-state diagnosis, not a before/after improvement. Native headless Chrome on one AMD/ANGLE D3D11 device, one dense global-belt viewpoint per scene. Cloud models/textures fetched normally, but their individual response bytes were not archived.',
      'Plain windows record renderFrame entry intervals and wall durations with a small wrapper; these are not screen presentation timestamps or direct GPU utilization. Short/long interval alternation makes 1000/p50 misleading as FPS.',
      'Movement is 2 TU (~3990.52 km) plus 360 degree yaw in 240 frame-indexed steps, not fixed real-time velocity. Simulation time continues, windows run in a fixed sequence, and cache/thermal/order effects are not controlled for before/after comparison.',
      'GPU modes run separately; elapsed scopes include command execution and may include submission gaps. Per-draw scopes omit surrounding renderer work, clears and MSAA resolves. Do not add medians, subtract cross-window medians as exact overhead, or compare instrumented cadence as FPS.',
      'CPU components nest and may include driver stalls. CDP spans measure() setup/cleanup as well as frames: idle, getError and snapshot getParameter samples outside the measured frames must not be treated as application-frame hotspots. No getParameter calls were intercepted inside either CPU frame window.',
      'Large CPU wall spikes from some plain windows did not recur in the separate CPU diagnostic windows. Their cause remains unlocalized; no tail-latency fix is claimed.',
      'The sourceModuleRequests guard matches root /src, /@vite, /@id and /tests paths, not every possible base-prefixed source path. The unchanged production bundle manifest and reviewed built-module-only probe are the primary evidence that no dev runtime was loaded.',
      'Screenshots and complete production output stay in ignored local artifacts and are indexed by SHA256; they are not embedded in this JSON. Diagnostic sources, raw measured samples, CPU profiles and logs are embedded. No visual-equivalence or full-scene coverage claim is made.',
      'Menu resource counts reset after both scenes, but this ~11-minute run is not a long heap/VRAM leak or GC-normalized memory test. JS heap snapshots are not comparable retained memory measurements.',
      'Three 0.182.0 resolves multisampled targets after renderer.render. resolveDepthBuffer=false is not a portable preserve-depth control: in its OculusBrowser invalidation branch it invalidates read and draw depth attachments. This branch is not active on the recorded Chrome. No resolve policy was changed and no redundant-resolve cost or speedup is proven.'
    ],
    nextTarget: {
      first: 'Measure individual asteroid material draws within RenderPass and gl.blitFramebuffer MSAA resolves in separate native GPU windows; attribute actual cost before changing the renderer.',
      subsequent: 'Select a bounded optimization from those measurements, then require paired baseline/candidate samples and depth/HDR image regression checks with MSAA 0/4 before retaining it. Dust/nebula raymarch and reconstruction fallback remain measured hotspots.',
      outstanding: ['Localize rare plain-window long frames with targeted tracing while preserving a plain cadence control', 'Long repeated scene transitions with GC-normalized heap and resource/VRAM evidence']
    },
    review: existsSync(reviewPath) ? json(reviewPath) : null,
    provenance: paths.map(path => { const bytes = readFileSync(path); return { path, bytes: bytes.length, sha256: sha(bytes) } })
  }
  verify(archive)
  writeFileSync(output, JSON.stringify(archive, null, 2) + '\n')
  console.log(output)
}
